from pathlib import Path
import subprocess, json
root=Path('designs/metalflow-os'); ds=root/'design-system'
css=''' :root{--bg:#f6f8f7;--surface:#fff;--text:#172e2a;--muted:#61736f;--border:#dce5e1;--accent:#176451;--soft:#e6f2ed;--radius:7px;--font:Inter,ui-sans-serif,system-ui,sans-serif;--space:8px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px var(--font)}button,input,select,textarea{font:inherit}button{cursor:pointer;background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:var(--radius);padding:9px 14px}button.primary{background:var(--accent);color:white}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #40a98b;outline-offset:3px}aside{position:fixed;width:238px;inset:0 auto 0 0;padding:25px 16px;background:var(--surface);border-right:1px solid var(--border)}.brand{font-size:20px;font-weight:750;letter-spacing:-.7px;margin:0 10px 30px}.brand span{color:var(--accent)}nav a{display:block;padding:10px 12px;color:var(--muted);text-decoration:none;border-radius:6px}nav a.active{background:var(--soft);color:var(--accent);font-weight:650}small,.muted{color:var(--muted)}nav small{display:block;margin:24px 12px 8px;text-transform:uppercase;font-size:10px;letter-spacing:1.5px}header{margin-left:238px;height:68px;border-bottom:1px solid var(--border);background:var(--surface);display:flex;align-items:center;justify-content:space-between;padding:0 36px}main{margin-left:238px;padding:30px 36px;max-width:1700px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}h1{font-size:27px;letter-spacing:-.7px;margin:8px 0}h2{font-size:15px;margin:0 0 20px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card,.panel{border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);padding:22px}.card strong{display:block;font-size:27px;font-weight:600;letter-spacing:-1px;margin:14px 0 8px}.grid{display:grid;grid-template-columns:1.7fr 1fr;gap:20px;margin-top:22px}.chart{height:180px;display:flex;align-items:end;gap:14px;border-bottom:1px solid var(--border);padding:0 15px}.bar{background:var(--accent);border-radius:3px 3px 0 0;flex:1;opacity:.8}.row{display:flex;justify-content:space-between;padding:16px 0;border-bottom:1px solid var(--border)}.badge{font-size:11px;padding:4px 8px;background:var(--soft);color:var(--accent);border-radius:4px}table{border-collapse:collapse;width:100%;text-align:left}th{font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted);font-weight:500}td,th{padding:15px 10px;border-bottom:1px solid var(--border)}input,select,textarea{padding:10px;border:1px solid var(--border);border-radius:6px;background:var(--surface);color:var(--text);width:100%}label{display:block;margin:14px 0 6px}footer{margin-top:28px;color:var(--muted);font-size:11px}.actions{display:flex;gap:8px}.dark{--bg:#101c19;--surface:#182622;--text:#ecf4f0;--muted:#a1b4ac;--border:#31463d;--soft:#223d32}.compact .card{padding:14px}.compact aside{background:#193b35;color:#fff}.compact nav a{color:#c9dbd5}.blue{--accent:#285a91;--soft:#e8f0fa;--bg:#f4f6fa}.amber{--accent:#805e27;--soft:#f7efdf;--bg:#faf8f3}@media(max-width:760px){aside{display:none}header,main{margin-left:0;padding:18px}.cards{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.panel{overflow:auto}.top{align-items:start;gap:14px}h1{font-size:23px}}'''
(ds/'styles.css').write_text('@import "tokens/foundation.css";\n');(ds/'tokens/foundation.css').write_text(css)
(ds/'readme.md').write_text('''# MetalFlow Foundry Design System
Source: https://github.com/jimliu/baoyu-design. Product context: metal distribution and renovation operations. Original identity informed by the supplied Linear/Stripe/Vercel references; no copied product UI.
## Content fundamentals
Sentence case, direct action labels, ISO currency codes, explicit uncertainty. No invented production metrics.
## Visual foundations
Warm neutral canvas, forest teal actions, 7px radii, 1px borders, no decorative gradients or shadows. System fonts with Chinese fallback. Spacing uses 8px rhythm. Tables prioritize identifiers, parties, status and amounts. Reduced motion supported. Light and dark themes share semantic tokens.
## Iconography
Production uses Lucide line icons. No emoji. No decorative images in operational views.
## Components
App shell, form fields, buttons, status badges, metric cards, tables, drawers and accessible dialogs. Native semantic controls in prototypes; Radix primitives and shadcn patterns in production.
''')
(ds/'SKILL.md').write_text('---\nname: metalflow-design\ndescription: MetalFlow OS visual system for operational workflows.\n---\nRead readme.md and use the CSS tokens. Preserve table density and clear status labels.\n')
(ds/'foundations.html').write_text('<!-- @dsCard group="Foundations" viewport="700x240" name="Tokens and controls" -->\n<!doctype html><html><head><link rel="stylesheet" href="styles.css"></head><body style="padding:25px"><h1>MetalFlow OS</h1><p>Clear decisions. Connected operations.</p><button class="primary">Create quotation</button> <button>Save draft</button> <span class="badge">Approved</span><label>Customer</label><input placeholder="Search customers"></body></html>')
nav=[('Overview','dashboard','Dashboard'),('','inquiries','Inquiry inbox'),('Sales & CRM','quotations','Quotations'),('','customers','Customers'),('','orders','Sales orders'),('Supply chain','inventory','Inventory'),('','procurement','Procurement'),('Operations','fabrication','Cutting optimization'),('','ai-design','Design studio'),('','takeoff','Drawing takeoff'),('','projects','Projects'),('Finance','finance','Invoices & payments'),('','analytics','Analytics'),('Workspace','settings','Team & permissions')]
rows={'inquiries':['SS304 tube · lobby handrails','Aluminum sheets · retail fit-out','316 round tube · coastal balcony'],'quotations':['QT-2026-0042 · Harbor Workshop','QT-2026-0041 · Northline Interiors','QT-2026-0040 · Cedar Build'],'customers':['Harbor Workshop · Contractor','Northline Interiors · Designer','Cedar Build · Business'],'orders':['SO-2026-0028 · Harbor Workshop','SO-2026-0027 · Northline Interiors'],'inventory':['SS304-SQ-40 · Square tube 40×40×2','AL6063-PL-3 · Aluminum plate 3 mm','SS316-RD-25 · Round tube 25 mm'],'procurement':['PO-2026-0017 · Alloy Source','PO-2026-0016 · Meridian Metals'],'projects':['Harbor office fit-out','Cedar residence','Northline retail showroom'],'finance':['INV-2026-0034 · Harbor Workshop','INV-2026-0033 · Cedar Build'],'settings':['Alex Morgan · Owner','Jordan Chen · Sales representative','Sam Patel · Warehouse manager']}
def page(section,title,variant='',special=''):
    links=''.join((f'<small>{g}</small>' if g else '')+f'<a href="../{key}/index.html" class="{"active" if key==section else ""}">{name}</a>' for g,key,name in nav)
    top=f'<div class="top"><div><small>Workspace / {title}</small><h1>{title}</h1><p class="muted">A clear view of what needs your attention.</p></div><div class="actions"><button onclick="document.body.classList.toggle(\'dark\')">Theme</button><button class="primary" onclick="document.getElementById(\'edit\').showModal()">Create new</button></div></div>'
    content=special
    if not content and section in ('dashboard','analytics'):
        content='<div class="cards">'+''.join(f'<div class="card"><small>{a}</small><strong>{b}</strong><small>{c}</small></div>' for a,b,c in [('Sales this month','$124,860','12 confirmed orders'),('Receivables','$28,450','6 open invoices'),('Open quotations','18','4 awaiting approval'),('Active projects','7','2 milestones this week')])+'</div><div class="grid"><section class="panel"><h2>Revenue overview <small> · USD · sample data</small></h2><div class="chart">'+''.join(f'<div class="bar" style="height:{h}%"></div>' for h in [30,45,35,60,55,75,62,90,78,95,83,98])+'</div><div class="row"><small>01 Oct</small><small>15 Oct</small><small>31 Oct</small></div></section><section class="panel"><h2>Needs attention</h2><div class="row">4 quotations await approval <span class="badge">Sales</span></div><div class="row">SS304 square tube below threshold <span class="badge">Stock</span></div><div class="row">Harbor milestone due Friday <span class="badge">Project</span></div></section></div>'
    if not content:
        body=''.join(f'<tr><td>{x}</td><td>29 Oct 2026</td><td><span class="badge">{("Reviewing" if section=="inquiries" else "Active")}</span></td><td><button onclick="document.getElementById(\'edit\').showModal()">View details</button></td></tr>' for x in rows.get(section,['Material review · main workspace','Saved operation · latest version']))
        content=f'<section class="panel"><div class="top"><input aria-label="Filter records" placeholder="Search records…" oninput="document.querySelectorAll(\'tbody tr\').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(this.value.toLowerCase()))"><button>All statuses</button></div><table><thead><tr><th>Record</th><th>Updated</th><th>Status</th><th>Action</th></tr></thead><tbody>{body}</tbody></table></section>'
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · MetalFlow OS prototype</title><style>{css}</style></head><body class="{variant}"><aside><div class="brand">▥ MetalFlow <span>OS</span></div><nav>{links}</nav></aside><header><strong>Foundry Supply Co. <small> / Demo workspace</small></strong><span class="muted">Search workspace　⌘ K</span></header><main>{top}{content}<footer>DESIGN PROTOTYPE · Fictional sample data · Not a production record</footer></main><dialog id="edit"><form method="dialog"><h2>{title} · review</h2><label>Record name</label><input required value="Harbor Workshop"><label>Notes</label><textarea>Review specifications before approval.</textarea><div class="actions"><button>Save in prototype</button><button formnovalidate>Close</button></div></form></dialog></body></html>'
for _,key,title in nav:
    d=root/key;d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(page(key,title))
for name,var in [('foundry',''),('precision','blue compact'),('studio','amber')]:
    (root/'dashboard'/f'{name}.html').write_text(page('dashboard',f'Operations overview · {name.title()}',var))
extra=[('inquiries','review','AI extraction review','<div class="grid"><section class="panel"><h2>Original inquiry</h2><p>Need 100 pcs SS304 square tube, 40x40x2mm, 6m length. Please quote.</p><span class="badge">Human review required</span></section><section class="panel"><h2>Extracted specifications</h2><label>Material / grade</label><input value="Stainless steel / 304"><label>Dimensions (mm)</label><input value="40 × 40 × 2 × 6000"><label>Quantity</label><input value="100"><label>Delivery date</label><input placeholder="Missing — ask customer"></section></div>'),('quotations','editor','New quotation','<section class="panel"><h2>Customer & terms</h2><label>Customer</label><input value="Harbor Workshop"><label>Valid until</label><input type="date" value="2026-11-15"><label>Line specification</label><input value="SS304 square tube 40×40×2 mm"><div class="grid"><div><label>Quantity</label><input type="number" value="100"></div><div><label>Unit price · USD</label><input value="48.00"></div></div><div class="row"><strong>Total before tax</strong><strong>USD 4,800.00</strong></div><button class="primary">Save draft</button></section>'),('inventory','product-editor','Product specification editor','<section class="panel"><label>SKU</label><input value="SS304-SQ-40"><label>Profile</label><select><option>Square tube</option><option>Sheet</option><option>Round tube</option></select><label>Width × height × wall × length (mm)</label><input value="40 × 40 × 2 × 6000"><label>Configured density (kg/m³)</label><input value="7930"><p class="muted">Weight uses configured geometry. Corner radii excluded from this approximation.</p></section>'),('settings','auth','Welcome to MetalFlow OS','<section class="panel" style="max-width:440px;margin:30px auto"><h1>Your operations, connected.</h1><p class="muted">Sign in to your workspace.</p><label>Email address</label><input type="email" placeholder="you@company.com"><label>Password</label><input type="password"><p><button class="primary">Sign in</button></p><small>Create an account · Reset password</small></section>')]
for group,name,title,content in extra:(root/group/f'{name}.html').write_text(page(group,title,special=content))
(root/'DESIGN_DECISION.md').write_text('''# Dashboard direction evaluation
| Direction | Hierarchy | Usability | Navigation | Density | Accessibility | Scalability |
|---|---|---|---|---|---|---|
| Foundry: neutral + forest teal | Strong | Strong | Clear groups | Balanced | High contrast | Strong |
| Precision: blue + dark rail | Strong | Dense | More visual weight | Highest | Good | Strong |
| Studio: warm editorial | Good | More relaxed | Clear | Lower | Good | Moderate |
Selected Foundry autonomously under the user\'s no-questions instruction. It balances financial tables, material specifications and project workflows. These are design judgments, not measured user-study scores.
Method: baoyu-design SKILL + system-prompt + hi-fi-design + interactive-prototype + design-system-authoring-guide. Skill installed with the documented CLI. Local prototype state is synthetic and never reused as production metrics. No human approval is claimed.
''')
